def svg(n,panels):
 w=720;ph=290;H=ph*len(panels);out=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {H}" role="img"><rect width="100%" height="100%" fill="#fff"/>']
 for j,(title,xlim,ylim,curves) in enumerate(panels):
  top=j*ph;X=lambda x:60+(x-xlim[0])/(xlim[1]-xlim[0])*620;Y=lambda y:top+245-(y-ylim[0])/(ylim[1]-ylim[0])*195
  out.append(f'<text x="60" y="{top+24}" font-size="15" fill="#172b4d">{html.escape(title)}</text><rect x="60" y="{top+50}" width="620" height="195" fill="#f6f8fc" stroke="#ccd5df"/>')
  for axis,val in [('x',0),('y',0)]:
   if axis=='x' and ylim[0]<=val<=ylim[1]:out.append(f'<path d="M60 {Y(0)}H680" stroke="#8894a4"/>')
   if axis=='y' and xlim[0]<=val<=xlim[1]:out.append(f'<path d="M{X(0)} {top+50}V{top+245}" stroke="#8894a4"/>')
  for z,(label,coords) in enumerate(curves):
   col=['#1463c2','#c44933','#17926f','#8953b4','#bf8800'][z%5];segments=[];path=''
   for x,y in coords:
    if math.isfinite(y) and ylim[0]<=y<=ylim[1]:path+=('M' if not path else 'L')+f'{X(x):.2f},{Y(y):.2f}'
    elif path:segments.append(path);path=''
   if path:segments.append(path)
   for path in segments:out.append(f'<path d="{path}" fill="none" stroke="{col}" stroke-width="2"/>')
   out.append(f'<text x="{65+(z%3)*205}" y="{top+263+(z//3)*17}" font-size="12" fill="{col}">{html.escape(label)}</text>')
  out.append(f'<text x="62" y="{top+45}" font-size="11">y: {ylim[0]} .. {ylim[1]}</text><text x="510" y="{top+45}" font-size="11">x/t: {xlim[0]} .. {xlim[1]}</text>')
 out.append('</svg>');p=AS/f's9-1-{n}.svg';p.write_text(''.join(out))
 ex=next(e for e in items if e['number']==n);ex['figure']={'src':f'../exercise-content/assets/{p.name}','alt':bi('해설의 함수로 생성한 개형과 해곡선','Shapes and solution curves generated from the functions in the explanation'),'caption':bi('자체 계산 도해. 축 범위와 각 곡선의 식 또는 매개변수를 표시했다.','Original computed diagram with axis ranges and formulas or parameters.')}
def sampled(f,a,b,N=500):return [(a+(b-a)*i/N,f(a+(b-a)*i/N)) for i in range(N+1)]
svg(18,[('Solution family: y=(ln x+C)/x',(.1,5),(-4,5),[(f'C={c:.3f}',sampled(lambda x:(math.log(x)+c)/x,.1,5)) for c in [-1,0,1,2,2-math.log(2)]])])
svg(20,[('Positive solution family: y=1/sqrt(c-x^2)',(-2,2),(0,8),[(f'c={c}',sampled(lambda x:1/math.sqrt(c-x*x),-.995*math.sqrt(c),.995*math.sqrt(c))) for c in [.25,1,4]])])
svg(23,[('Schematic contradiction (a): a decreasing segment',(-1,4),(-.5,3),[('y=1+0.25(t-1)^3-0.1(t-1)^4',sampled(lambda t:1+.25*(t-1)**3-.1*(t-1)**4,-.4,4))]),('Schematic contradiction (b): crossing y=1 with positive slope',(-1,4),(-.5,3),[('y=1+tanh(t-1)',sampled(lambda t:1+math.tanh(t-1),-1,4)),('y=1',sampled(lambda t:1,-1,4))])])
def rk(f,a,b,y0,N=1200):
 h=(b-a)/N;x=a;y=y0;pts=[(x,y)]
 for i in range(N):
  k1=f(x,y);k2=f(x+h/2,y+h*k1/2);k3=f(x+h/2,y+h*k2/2);k4=f(x+h,y+h*k3)
  y+=h*(k1+2*k2+2*k3+k4)/6;x=a+(i+1)*h;pts.append((x,y))
 return pts
def both(f,b,y=0):return list(reversed(rk(f,0,-b,y)))+rk(f,0,b,y)[1:]
svg(24,[('C: y prime = 1-2xy, y(0)=2',(-1.5,4),(0,3),[('RK4 solution',list(reversed(rk(lambda x,y:1-2*x*y,0,-1.5,2)))+rk(lambda x,y:1-2*x*y,0,4,2)[1:])])])
svg(25,[('I: (b)',(-2,2),(-.1,.7),[('y prime = x exp(-x^2-y^2)',both(lambda x,y:x*math.exp(-x*x-y*y),2))]),('II: (d)',(-2,2),(-1,1),[('y=0',sampled(lambda x:0,-2,2))]),('III: (a)',(-1,1),(-3,3),[('y prime = 1+x^2+y^2',both(lambda x,y:1+x*x+y*y,1))]),('IV: (c)',(-3,3),(-1,1),[('y prime = 1/(1+exp(x^2+y^2))',both(lambda x,y:1/(1+math.exp(x*x+y*y)),3))])])
