svg(27,[('Learning example: M=1, P(0)=0, k=1',(0,5),(0,1.1),[('P=1-exp(-t)',sampled(lambda t:1-math.exp(-t),0,5)),('maximum M=1',sampled(lambda t:1,0,5))])])
svg(28,[('Fish growth example: asymptotic length=10, L(0)=2, k=1',(0,5),(0,11),[('L=10-8 exp(-t)',sampled(lambda t:10-8*math.exp(-t),0,5)),('asymptotic length=10',sampled(lambda t:10,0,5))])])
